<script setup lang="ts">
import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{ArrowLeft,Clock,Eye,MapPin,MessageCircle,Send,Stethoscope,UserRound}from'@lucide/vue';import{api,apiError}from'@/services/api';import type{ClinicalCase}from'@/types';import StatusPill from'@/components/StatusPill.vue';import{useLocaleStore}from'@/stores/locale'
const route=useRoute(),locale=useLocaleStore(),item=ref<ClinicalCase|null>(null),loading=ref(true),error=ref(''),previewQuestion=ref(''),previewReply=ref(''),previewFacts=ref<Array<{id?:string;label?:string;value?:string}>>([]),previewing=ref(false),previewError=ref('');async function load(){loading.value=true;error.value='';try{item.value=await api.getCase(String(route.params.id))}catch(e){error.value=apiError(e)}finally{loading.value=false}}onMounted(()=>void load());async function testPatient(){const message=previewQuestion.value.trim();if(!message||previewing.value||!item.value)return;previewing.value=true;previewError.value='';previewReply.value='';previewFacts.value=[];try{const result=await api.previewCaseResponse(item.value.id,message);previewReply.value=result.text;previewFacts.value=result.permittedFacts}catch(e){previewError.value=apiError(e,locale.t('The AI patient preview failed.'))}finally{previewing.value=false}}
</script>
<template><div class="page"><RouterLink class="text-button" :to="`/faculty/cases/${route.params.id}/edit`"><ArrowLeft :size="16"/>{{locale.t('Back to editor')}}</RouterLink><div v-if="loading" class="loading" role="status"><div class="spinner"></div><span class="sr-only">{{locale.t('Loading')}}</span></div><section v-else-if="error" class="card empty" role="alert"><h2>{{locale.t('The case preview could not be loaded.')}}</h2><p>{{error}}</p><button class="button" type="button" @click="load">{{locale.t('Try again')}}</button></section><template v-else-if="item"><header class="page-header"><div><div class="page-eyebrow">{{locale.t('Educator preview')}}</div><h1 data-no-translate lang="en-AU">{{item.title}}</h1><p class="subtitle">{{locale.t('Review the student-facing brief alongside the structured patient identity before publication.')}}</p></div><StatusPill :value="item.status"/></header><div class="preview-grid"><section class="preview-main"><section class="preview-screen card"><div class="preview-screen__bar"><span><Eye :size="15"/>{{locale.t('Student view')}}</span><small>{{locale.t('Case')}} {{item.id}} · v{{item.version}}</small></div><div class="preview-screen__body"><span class="preview-icon"><Stethoscope/></span><div class="page-eyebrow">{{locale.t(item.specialty)}} · {{locale.t(item.difficulty)}}</div><h2 data-no-translate lang="en-AU">{{item.title}}</h2><p data-no-translate lang="en-AU">{{item.subtitle}}</p><div class="preview-meta"><span><MapPin :size="14"/>{{locale.t(item.setting)}}</span><span><Clock :size="14"/>{{item.durationMinutes}} {{locale.t('minutes')}}</span></div><div class="task"><b>{{locale.t('Your task')}}</b><p data-no-translate lang="en-AU">{{item.task}}</p></div><div><b>{{locale.t('Learning focus')}}</b><ul><li v-for="objective in item.learningObjectives" :key="objective" data-no-translate lang="en-AU">{{objective}}</li></ul></div></div></section></section><aside class="card card--padded"><div class="side-heading"><UserRound/><h2>{{locale.t('Patient identity')}}</h2></div><dl><dt>{{locale.t('Name')}}</dt><dd data-no-translate lang="en-AU">{{item.patientName||locale.t('Not specified')}}</dd><dt>{{locale.t('Age')}}</dt><dd>{{item.patientAge||locale.t('Not specified')}}</dd><dt>{{locale.t('Presenting complaint')}}</dt><dd data-no-translate lang="en-AU">{{item.presentingComplaint||locale.t('Stored in structured case data')}}</dd><dt>{{locale.t('Linked rubric')}}</dt><dd>{{item.rubricId?`${locale.t('Rubric')} ${item.rubricId}`:locale.t('No rubric linked')}}</dd></dl><RouterLink class="button button--secondary" :to="`/faculty/cases/${item.id}/edit`">{{locale.t('Edit case')}}</RouterLink></aside></div><section class="card card--padded ai-preview"><div class="side-heading"><MessageCircle/><h2>{{locale.t('AI patient test')}}</h2></div><p class="subtitle">{{locale.t('Test a few student questions before publishing and inspect which facts were disclosed.')}}</p><form class="ai-preview__form" @submit.prevent="testPatient"><label class="sr-only" for="preview-question">{{locale.t('Question for the simulated patient')}}</label><textarea id="preview-question" v-model="previewQuestion" class="textarea" rows="2" maxlength="2000" :placeholder="locale.t('Try a question, for example: When did it start?')" :disabled="previewing"></textarea><button class="button" :disabled="previewing||!previewQuestion.trim()"><Send :size="16"/>{{previewing?locale.t('Testing…'):locale.t('Test patient')}}</button></form><div v-if="previewError" class="alert alert--error" role="alert">{{previewError}}</div><div v-if="previewReply" class="ai-preview__result"><div class="ai-preview__reply"><b>{{locale.t('Patient response')}}</b><p data-no-translate lang="en-AU">{{previewReply}}</p></div><div class="ai-preview__facts"><b>{{locale.t('Facts disclosed this turn')}}</b><span v-if="!previewFacts.length">{{locale.t('No structured fact was disclosed.')}}</span><ul v-else><li v-for="fact in previewFacts" :key="fact.id" data-no-translate lang="en-AU"><strong>{{fact.label||fact.id}}</strong><span>{{fact.value}}</span></li></ul></div></div></section></template></div></template>
<style scoped>.preview-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:18px}.preview-screen{overflow:hidden}.preview-screen__bar{padding:11px 16px;background:#edf3f0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;font-size:10px;color:var(--muted)}.preview-screen__bar span{display:flex;gap:6px;align-items:center;color:var(--green);font-weight:700}.preview-screen__body{padding:clamp(26px,5vw,55px)}.preview-screen__body h2{font-size:34px}.preview-screen__body>p{color:var(--muted)}.preview-icon{display:grid;place-items:center;width:50px;height:50px;border-radius:14px;background:var(--green-soft);color:var(--green);margin-bottom:20px}.preview-meta{display:flex;gap:18px;font-size:11px;color:var(--muted);margin:20px 0}.preview-meta span{display:flex;gap:5px;align-items:center}.task{padding:18px;background:#f5f8f6;border-radius:11px;margin:20px 0}.task p{margin:6px 0 0;font-size:13px;color:#56645f}.preview-screen ul{color:#56645f;font-size:12px}.side-heading{display:flex;gap:9px;color:var(--green);align-items:center}.side-heading svg{flex:none}.side-heading h2{color:var(--ink);font-size:20px;margin:0}.preview-grid aside dl{margin:18px 0}.preview-grid dt{font-size:9px;text-transform:uppercase;color:#84918c;font-weight:700;letter-spacing:.08em}.preview-grid dd{margin:3px 0 14px;font-size:12px}.preview-grid aside .button{width:100%}.ai-preview{margin-top:18px}.ai-preview .subtitle{max-width:720px;margin:4px 0 16px}.ai-preview__form{display:flex;gap:10px;align-items:flex-end}.ai-preview__form .textarea{flex:1;min-height:76px;resize:vertical}.ai-preview__form .button{flex:none;display:inline-flex;align-items:center;gap:7px;min-height:42px}.ai-preview__result{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(240px,1fr);gap:14px;margin-top:16px}.ai-preview__reply,.ai-preview__facts{border:1px solid var(--line);border-radius:10px;padding:14px;background:#fbfcfb}.ai-preview__reply p{margin:8px 0 0;line-height:1.6;color:#33433d;font-size:13px}.ai-preview__facts>span{display:block;color:var(--muted);font-size:12px;margin-top:8px}.ai-preview__facts ul{list-style:none;margin:9px 0 0;padding:0;display:grid;gap:8px}.ai-preview__facts li{display:grid;gap:2px;padding:8px 10px;background:#f1f6f3;border-radius:7px;font-size:11px}.ai-preview__facts li strong{font-size:11px;color:var(--green)}.ai-preview__facts li span{color:#4e5d57;line-height:1.4}@media(max-width:850px){.preview-grid{grid-template-columns:1fr}.preview-grid aside{grid-row:1}.ai-preview__form{display:grid}.ai-preview__form .button{justify-content:center}.ai-preview__result{grid-template-columns:1fr}}
</style>
